INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'After flashing new firmware onto a Zigbee coordinator, all previously paired devices show as unreachable. What is the most likely cause and correct remediation?', 'بعد برمجة برنامج ثابت جديد على منسق Zigbee، تظهر كل الأجهزة المقترنة سابقًا كغير قابلة للوصول. ما السبب الأرجح والإصلاح الصحيح؟', 1 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'gold';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'The network''s PAN ID/encryption key changed with the reflash, so devices must be individually re-joined; restoring a backed-up network key can avoid this', 'تغيّر معرف الشبكة/مفتاح التشفير مع إعادة البرمجة، لذا يجب إعادة ضم الأجهزة فرديًا؛ استعادة مفتاح شبكة محفوظ مسبقًا يمكن أن يتجنب ذلك', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'gold' AND qq.question = 'After flashing new firmware onto a Zigbee coordinator, all previously paired devices show as unreachable. What is the most likely cause and correct remediation?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'The devices are permanently broken and must be replaced', 'الأجهزة معطلة بشكل دائم ويجب استبدالها', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'gold' AND qq.question = 'After flashing new firmware onto a Zigbee coordinator, all previously paired devices show as unreachable. What is the most likely cause and correct remediation?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'This only happens with Wi-Fi devices, not Zigbee', 'يحدث هذا فقط مع أجهزة Wi-Fi لا Zigbee', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'gold' AND qq.question = 'After flashing new firmware onto a Zigbee coordinator, all previously paired devices show as unreachable. What is the most likely cause and correct remediation?';
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'silver', title || ' — Silver Quiz', title_ar || ' — اختبار فضي', 85 FROM public.modules WHERE slug = 'sonoff-network-troubleshooting';
INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'A large property''s Zigbee network works fine near the gateway but battery sensors on the far side keep dropping. Routers are mains-powered devices spread throughout. What''s the likely diagnosis?', 'شبكة Zigbee في عقار كبير تعمل جيدًا قرب البوابة لكن حساسات البطارية في الجانب البعيد تنقطع باستمرار. الموجّهات أجهزة متصلة بالكهرباء منتشرة في كل مكان. ما التشخيص الأرجح؟', 1 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'silver';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Insufficient router density or hop count on the far side of the mesh, requiring an additional repeater there', 'كثافة موجّهات أو عدد قفزات غير كافٍ في الجانب البعيد من الشبكة، ما يتطلب معيد إشارة إضافي هناك', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'silver' AND qq.question = 'A large property''s Zigbee network works fine near the gateway but battery sensors on the far side keep dropping. Routers are mains-powered devices spread throughout. What''s the likely diagnosis?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'The battery sensors need a firmware downgrade', 'الحساسات تحتاج خفض إصدار البرنامج الثابت', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'silver' AND qq.question = 'A large property''s Zigbee network works fine near the gateway but battery sensors on the far side keep dropping. Routers are mains-powered devices spread throughout. What''s the likely diagnosis?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Battery sensors cannot work more than 5 meters from a gateway under any circumstances', 'لا يمكن لحساسات البطارية العمل على بعد أكثر من 5 أمتار من البوابة تحت أي ظرف', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'silver' AND qq.question = 'A large property''s Zigbee network works fine near the gateway but battery sensors on the far side keep dropping. Routers are mains-powered devices spread throughout. What''s the likely diagnosis?';
