INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'You''re designing a two-gateway deployment for a large estate where zones must share automations (e.g. a single ''goodnight'' scene across the whole property). What must be carefully coordinated between the gateways?', 'تصمم نشر بوابتين لعقار كبير حيث يجب أن تشترك المناطق في الأتمتة (مثل مشهد ''ليلة سعيدة'' واحد للعقار بأكمله). ما الذي يجب تنسيقه بعناية بين البوابتين؟', 1 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'gold';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Channel assignment and PAN ID planning to run as a single extended network, or a higher-level automation platform that bridges both gateways'' scenes', 'تخصيص القناة وتخطيط معرف الشبكة للعمل كشبكة موسعة واحدة، أو منصة أتمتة أعلى تربط مشاهد البوابتين', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'gold' AND qq.question = 'You''re designing a two-gateway deployment for a large estate where zones must share automations (e.g. a single ''goodnight'' scene across the whole property). What must be carefully coordinated between the gateways?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Nothing — gateways automatically share automations by default', 'لا شيء — البوابات تشارك الأتمتة تلقائيًا افتراضيًا', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'gold' AND qq.question = 'You''re designing a two-gateway deployment for a large estate where zones must share automations (e.g. a single ''goodnight'' scene across the whole property). What must be carefully coordinated between the gateways?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'The gateways must be physically connected by an Ethernet cable to share any state', 'يجب توصيل البوابتين فعليًا بكابل إيثرنت لمشاركة أي حالة', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-network-troubleshooting' AND q.tier = 'gold' AND qq.question = 'You''re designing a two-gateway deployment for a large estate where zones must share automations (e.g. a single ''goodnight'' scene across the whole property). What must be carefully coordinated between the gateways?';
